      : invoice.lines.map((line, i) => (i === existingLineIndex ? { ...line, qty: line.qty + qty } : line));

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {object} invoice
 * @param {string} sku
 */
export function removeLine(invoice, sku) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check line exists
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  // Check it's not the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue an invoice (change status to 'issued' and assign a number).
 * @param {object} invoice
 * @param {Array<string>} existingNumbers - Invoice numbers already used
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Get next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

function isValidDate(dateString) {
  // Check format is YYYY-MM-DD
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateString)) return false;

  // Check it's a valid date
  const date = new Date(`${dateString}T00:00:00Z`);
  const [year, month, day] = dateString.split('-').map(Number);

  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() + 1 === month &&
    date.getUTCDate() === day
  );
}

