import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2025-10-07');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);

  const line1 = result.value.lines[0];
  assert.equal(line1.sku, 'DES-HOUR');
  assert.equal(line1.name, 'Design work (hour)');
  assert.equal(line1.qty, 5);
  assert.equal(line1.unitPrice, 8500);
  assert.equal(line1.vatRate, 21);

  const line2 = result.value.lines[1];
  assert.equal(line2.sku, 'DEV-HOUR');
  assert.equal(line2.name, 'Development (hour)');
  assert.equal(line2.qty, 3);
});

test('createInvoice reports CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports DATE_INVALID for invalid date format', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '10/07/2025',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports DATE_INVALID for impossible dates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-30',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports NO_LINES for empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [],
  });

  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports QTY_INVALID for zero quantities', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 0 }],
  });

  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports QTY_INVALID for negative quantities', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: -5 }],
  });

  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports QTY_INVALID for non-integer quantities', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2.5 }],
  });

  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports UNKNOWN_SKU for unknown product', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'NOPE-SKU', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate the input lines', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 5 }];
  const originalLine = { ...lines[0] };

  createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines,
  });

  assert.deepEqual(lines[0], originalLine);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 8500 }), 42500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 1250 }), 1250);
  assert.equal(lineTotal({ qty: 100, unitPrice: 50 }), 5000);
});

test('invoiceTotals sums line totals and sets total equal to subtotal', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
      { qty: 3, unitPrice: 9500 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5 * 8500 + 3 * 9500);
  assert.equal(totals.subtotal, 71000);
  assert.equal(totals.total, 71000);
});

test('invoiceTotals works with a single line', () => {
  const invoice = {
    lines: [{ qty: 2, unitPrice: 6000 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 12000);
  assert.equal(totals.total, 12000);
});

test('invoiceTotals works with an empty lines array', () => {
  const invoice = { lines: [] };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('addLine adds a new line to an invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[1].qty, 3);
});

test('addLine increases qty if SKU is already on the invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].qty, 8);
});

test('addLine reports QTY_INVALID for invalid quantities', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;

  let result = addLine(invoice, { sku: 'DEV-HOUR', qty: 0 });
