test('issueInvoice assigns a number and sets status to issued', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;

  const result = issueInvoice(invoice, []);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2025-0001');
  assert.equal(result.value.status, 'issued');
});

test('issueInvoice uses existing numbers to determine the next number', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;

  const existing = ['INV-2025-0001', 'INV-2025-0002', 'INV-2025-0003'];
  const result = issueInvoice(invoice, existing);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2025-0004');
});

test('issueInvoice handles different years independently', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-05-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;

  const existing = ['INV-2025-0100', 'INV-2026-0001'];
  const result = issueInvoice(invoice, existing);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2026-0002');
});

test('issueInvoice reports NOT_DRAFT for non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const result = issueInvoice(invoice, []);
  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice preserves other invoice properties', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;

  const result = issueInvoice(invoice, []);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2025-10-07');
  assert.equal(result.value.lines.length, 1);
});

test('issueInvoice does not mutate the input invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
